mode=[('自家用車・社用車・公用車',3797,76.8,5,2.5),('レンタカー',420,8.5,51,25.5),('JR在来線',203,4.1,47,23.5),('貸切・観光バス',184,3.7,41,20.5),('市内バス',174,3.5,31,15.5),('高速バス',82,1.7,41,20.5),('タクシー・ハイヤー',59,1.2,17,8.5),('バイク',128,2.6,1,.5),('その他',125,2.5,17,8.5),('無回答',57,1.2,27,13.5)]
body='<p class="intro">別府への来訪手段と、県内で利用した交通、住民の日常移動は別の問いです。使える県データは県の参考値として示し、市の交通利用実績と分けます。</p><div class="note warning"><strong>別府の観光客だけの交通手段構成比は、公表表で確認できていません。</strong><br>市の交通計画にある観光交通グラフも2019年度の大分県調査を引用しています。以下は最新の県全体調査で、市の円グラフにはしません。</div>'
body+='<div class="split"><article class="panel"><span class="scope">県内20観光地点・全回答4,942人</span><h3>県内で利用した足</h3>'+bars([(x[0],x[2]) for x in mode[:7]],100,'%')+'</article><article class="panel"><span class="scope">同調査・海外居住200人</span><h3>海外からの旅行者は、複数の足で</h3>'+bars([(x[0],x[4]) for x in mode[:7]],100,'%',C[2])+'</article></div><p class="note">2025年度の現地アンケート。各季3日、計12日の土日調査。<strong>複数回答なので合計100%にはならず、円グラフにしません。</strong>海外居住は国籍ではない区分です。別府の2地点は地獄めぐり265人・ロープウェイ266人ですが、この531人の手段別集計は公表表では確認できません。</p>'
body+=detail('交通手段の回答人数・母数・原表不一致',table('県内で利用した手段（複数回答）',['手段','全体 人','全体 %','海外 人','海外 %'],mode,True)+'<p class="micro">県PDF23頁のグラフはバイク2.5%・その他2.6%、24頁の表はバイク128人2.6%・その他125人2.5%で不一致。本表は人数と整合する24頁の表を採用しています。全体の同行人数14,984人はこの設問の分母ではありません。</p>')+link(S['survey']+'#page=24','県2025年度観光実態調査・23〜24頁')
body+='<div class="split"><article><h3>観光客と、市民の日常も分ける</h3><p class="intro">2021年の市民853人調査では、日常的に最も多く利用する手段の自動車・バイクが59.1%、鉄道・バス・タクシー・乗合タクシー合計が14.4%。観光客の交通比率ではありません。</p>'+link(S['plan'],'市交通計画12頁・市民アンケート')+'</article><article><h3>交通への改善希望は「回答」で読む</h3><p class="intro">県調査では交通渋滞・駐車場を挙げた人が422人（8.5%）、観光地への交通機関が227人（4.6%）。海外居住者では後者が32人（16.0%）でした。</p><p class="micro">全体4,942人、海外居住200人の複数回答。実際の渋滞延長や待ち時間、別府の困難率ではありません。</p>'+link(S['survey']+'#page=35','県調査・改善希望34〜35頁')+'</article></div>'
body+='<h3 style="margin-top:45px">観光バスは、実績と設備・予定を混ぜない</h3><div class="triple">'
for label,num,unit,desc,url in [('鉄輪地獄地帯公園・小倉地区','6','台','大型車の駐車収容台数。要予約、24時間以内1,000円。市全体の到着台数・入庫実績ではありません。','https://www.city.beppu.oita.jp/sisetu/kouen_tyuusyajyou/03kouen_03-02kannawa.html'),('定期観光・別府地獄めぐり','3','時間','7地獄を巡る予定所要時間。別府駅9:20／14:00発の2設定。成人4,500円（入場料込）。市平均滞在時間ではありません。','https://kamenoibus.com/sightseeing_jigoku/'),('秋のオープントップバス','46','席','導入1台の定員。2026/10/7〜12/13、一部運休あり。別府–由布院各方向3便、約65分。実乗車人数ではありません。','https://kamenoibus.com/archive/3690.html')]:
 body+=f'<article class="panel"><h3>{label}</h3><p class="big-number" style="color:var(--orange)">{num}<small>{unit}</small></p><p class="micro">{desc}</p>{link(url,"公式案内")}</article>'
body+='</div><p class="note warning"><strong>別府市全体の年間観光バス到着台数・乗客数は今回の調査で公表値を確認できていません。</strong><br>県の貸切・観光バス回答184人（3.7%）を市の733万人に掛けたり、定員×予定便数で来訪者数を作ることはできません。</p>'
body+='<h3 style="margin-top:45px">鉄道・バス・港には、別々の実績がある</h3><div class="metric-grid"><div class="metric"><p class="label">JR別府駅・2025年度</p><p class="big-number">5,925<small>人/日</small></p><p class="micro">1日平均乗車。降車を含まない。通勤・通学・観光を含む。</p></div><div class="metric"><p class="label">市統計書のバス利用・2024年</p><p class="big-number">565.5<small>万人</small></p><p class="micro">亀の井・大分交通・九州産交の掲載集計。市内観光客だけではない。</p></div><div class="metric"><p class="label">別府港2社の下船計・2024年</p><p class="big-number">20.18<small>万人</small></p><p class="micro">さんふらわあ121,800人＋宇和島運輸79,993人。観光目的限定ではない。</p></div></div>'
body+=detail('鉄道3駅の乗車人員と、港・空港・バスの年次実績',table('JR九州・1日平均乗車人員（人/日）',['駅','2024年度','2025年度'],[['別府',5961,5925],['別府大学',1785,1715],['亀川',1317,1291],['3駅算術合計',9063,8931]])+link(S['jr'],'JR九州2025年度駅別乗車人員')+table('市統計書掲載のバス利用人員（各社集計、人）',['年','合計','亀の井','大分交通','九州産交'],[[2022,5077695,2713425,2333070,31200],[2023,6319349,3718271,2543496,57582],[2024,5654799,3004503,2578466,71830]],True)+table('市統計書掲載の港・空港旅客（人）。空港は県全体',['年','さんふらわあ 乗/下船','宇和島運輸 乗/下船','大分空港 搭乗/降機'],[[2022,'71,787 / 64,759','56,534 / 53,743','643,707 / 649,785'],[2023,'115,704 / 111,075','72,894 / 70,243','855,520 / 865,492'],[2024,'126,730 / 121,800','81,730 / 79,993','932,035 / 944,944']],True)+link(S['stats'],'市令和7年版統計書・第10章89頁'))
body+='<div class="panel" style="margin-top:30px"><span class="scope">2026年GW・4/29〜5/6の8日間・速報</span><h3>繁忙期の車と船を、期間を揃えて見る</h3>'+table('別府市GW観光動態調査速報',['指標','値','対象・注意'],[['高速道路乗降車','135,300台','前年比+6.1%。流入のみ・観光のみ・ユニーク車両ではない'],['船舶降客 / 降車','9,333人 / 3,589台','船から降りた人・車。高速道路との重複不明'],['観光13施設入場','延べ227,364人','同じ人の施設間重複を含む'],['市内主要宿泊34施設','59,705人','全宿泊施設の総数ではない']])+'<p class="micro">曜日配列や対象施設の違いを踏まえた速報値です。異なる指標を足して観光客総数にしません。</p>'+link(S['gw'],'市2026年GW速報')+'</div>'
body+='<h3 style="margin-top:45px">路線の供給を、運行回数と乗車密度で見る</h3>'+table('県2026計画収録・2024年度の系統別輸送実績',['分類','系統数','運行回数','平均乗車密度','輸送量'],[['別府地域内',46,395.5,12.9,5111.7],['大分〜別府',3,22.0,6.1,134.4],['別府〜湯布院',6,20.5,5.9,121.2],['別府〜日出',2,3.5,2.1,7.3]],True)+'<p class="note">運行回数は1日当たりの原表値。平均乗車密度は輸送人キロ÷走行キロで、1便の乗車人数ではありません。原表の「輸送量」も<strong>年間利用者数や実人数に呼び換えません</strong>。片道・往復の扱いと輸送量の算式は当該表で明確でなく、ここでは原表名を保持します。2026年の現行ダイヤではありません。</p>'+link(S['vision_data'],'県ビジョン資料編78〜82頁')
body+='<h3 style="margin-top:45px">GLOBALは、どこからどこへ使われたか</h3><p class="intro">2025年5月3日〜9月15日のドライバー聞き取りOD2,171件では、交通結節点への降車が25.0%。交通結節点への移動にも使われています。</p><div class="split"><article class="panel"><h3>乗った場所</h3>'+ring([('観光施設・温泉',603),('宿泊施設',369),('飲食・買物',482),('交通結節点',291),('その他（差分計算）',426)],2171,'13.4','交通結節点','件')+'</article><article class="panel"><h3>降りた場所</h3>'+ring([('観光施設・温泉',580),('宿泊施設',487),('飲食・買物',316),('交通結節点',543),('その他（差分計算）',245)],2171,'25.0','交通結節点','件')+'</article></div><p class="note warning">これは<strong>国交省審議会に提出された連絡協議会の聞き取り速報</strong>です。実車総数5,187件（2025/4/28昼〜9/21・147日）とは集計期間と標本が異なります。乗客人数ではなく乗車案件。原表の平均34.0件/日は総数÷147と一致しないため採用しません。ODから追加需要・夜間外出増・消費効果を断定しません。</p>'+link(S['global_report']+'#page=10','2025/9/29全国自治体ライドシェア連絡協議会提出資料・7/9頁')
body+='<div class="split"><article class="panel"><h3>市街地の人流を見る別の資料</h3><p class="intro">県計画は2024年10月の携帯人流を掲載。別府駅・沿岸部、由布院駅とのつながりが確認できます。</p><p class="micro">大分・別府・由布の中部圏内225,126トリップ。18歳以上、地図は10トリップ以上のOD。観光客だけの集計ではなく、採用端末・拡大推計等の詳細は当該章に不足。「自動車」からバス・タクシーを分離できません。</p>'+link(S['vision_data'],'県資料編27頁・中部圏人流')+'</article><article><h3>低速 ＝ 渋滞、とは限らない</h3><p class="intro">国の2025年渋滞協議会は、駅前本町交差点の現地調査で目立つ渋滞がないと評価。ETC2.0の低速度には信号待ちの影響があり、解除候補としました。</p><p class="micro">2025/6/21昼の調査等。一方、クルーズ寄港日のタクシー・バス待ち列は2025/5/10・5/18の写真で確認できます。どちらも別府全体・通年の状況に一般化しません。</p>'+link(S['congestion'],'国交省2025/8/29渋滞協議会・17/37頁')+'</article></div>'
body+='<h3 style="margin-top:45px">いま使える交通と、運休・利用条件</h3><div class="route-grid">'
routes=[('空港 → 別府駅・北浜','1,600','円','エアライナー成人片道の普通運賃。停車地・便・所要時間は月別時刻表で確認。','https://www.oitakotsu.co.jp/bus/airport/unchin.php'),('大阪 → 別府','翌朝','着','さんふらわあは通常1日1往復。曜日別時刻と検査休航等あり。大阪発日〜木19:05→翌6:55、金土20:05→7:55。','https://www.ferry-sunflower.co.jp/route/osaka-beppu/time/'),('八幡浜 ↔ 別府','6','便/方向','宇和島運輸の掲載時刻。八幡浜発約2時間50分、別府発約2時間45分。運休・変更は公式確認。','https://www.uwajimaunyu.co.jp/sp/timetable/timetable.html'),('別府 → 由布院','36','番','観光快速ゆふりんは2026/10/17から当面全便運休。鉄輪からは別府駅西口経由で36番へと公式案内。','https://kamenoibus.com/archive/3724.html'),('亀の井バス市内1日ミニ','1,100','円','2026/7/1〜12/31使用分。ワイド1日1,800円、2日2,800円。JRや全事業者共通ではありません。','https://ticket-kamenoibus.book.ntmg.com/'),('GLOBAL・実証予定','2027.3','まで','2027/3/31まで予定。Uber/GO、電話不可。24時間365日の枠でも配車不能な場合あり。別府市が出発または到着。','https://www.city.beppu.oita.jp/seikatu/bouhan_anzen/koukyou_koutuu/rideshare4.html')]
for title,val,unit,desc,url in routes:body+=f'<article class="route"><span class="status">公式案内 / 2026.11.04確認</span><h3>{title}</h3><p class="route-value">{val}<small>{unit}</small></p><p>{desc}</p>{link(url,"最新の公式案内")}</article>'
body+='</div><p class="note">2026/10/1から亀の井10番・別府駅西口浜脇線も休止。代替として南部循環線を案内しています。古い路線図や、ゆふりんを勧める券販売ページより、最新の運休告知を優先してください。'+link('https://kamenoibus.com/archive/3713.html','10番休止の事業者告知')+'</p>'
body+='<h3 style="margin-top:45px">荷物と宿の接続も、移動の一部</h3><div class="route-grid">'
for title,desc,url in [('駅ヤマトの一時預かり・宿配送','別府えきマチ1丁目営業所の公式案内に一時預かりと当日配送。営業所は9:00〜19:00。ホテル当日配送の締切・対象宿・料金は別条件で、宅急便の発送締切と混同しません。','https://www.ekimachi1.com/beppu/floor/yamatounyu'),('WANDER COMPASS BEPPU','駅前観光案内所が荷物預かり、別府・由布院・大分・日出町のホテル配送を案内。対象宿・受付時間・料金は利用日の公式確認が必要です。','https://beppuinfo.jp/'),('特定3ホテルの無料荷物配送','大江亭・清海荘・三泉閣の宿泊客向け。ホテルフジヨシへ14時まで預け、宿で15時以降受取。帰路は宿へ10時まで、駅側11時以降。市全域の共通サービスではありません。','https://www.beppuonsen-hotels.com/page9'),('空港バスの手ぶら配送は中止中','大分交通の現行ページは2020/4/18から当面中止と表示。空港客貨混載の旧紹介だけで現在利用できるとは案内しません。駅の荷物配送とは別サービスです。','https://www.oitakotsu.co.jp/bus/airport/handsfree.php')]:body+=f'<article class="route"><h3>{title}</h3><p>{desc}</p>{link(url,"提供者の条件を確認")}</article>'
body+='</div><p class="note">荷物配送の実利用件数、宿送迎の市横断実車・費用、到着便と迎えの接続成功率は今回確認できていません。設備や提供施設数だけで、需要が満たされているとは判断しません。</p>'
